import axios from "axios";

// When the KDS page is opened from another device on the LAN (kitchen PC →
// http://<mac-ip>:3000), a "localhost" backend URL would point at that
// device itself — swap in the host the page was served from.
// Desktop exe (bhojpekds/desktop) injects the KDS server URL chosen on its
// setup screen; it wins over the build-time value.
const BACKEND_URL = (() => {
  const desktop = typeof window !== "undefined" && window.kdsDesktop && window.kdsDesktop.backendUrl;
  if (desktop) return String(desktop).replace(/\/$/, "");
  const raw = process.env.REACT_APP_BACKEND_URL || "";
  try {
    const u = new URL(raw);
    const local = ["localhost", "127.0.0.1"];
    if (local.includes(u.hostname) && !local.includes(window.location.hostname)) {
      u.hostname = window.location.hostname;
    }
    return u.toString().replace(/\/$/, "");
  } catch (e) {
    return raw;
  }
})();

const BASE = `${BACKEND_URL}/api`;

const api = axios.create({ baseURL: BASE, timeout: 12000 });

let actorName = "Kitchen Device";
export const setActor = (name) => {
  actorName = name || "Kitchen Device";
};

// The paired branch's device token (from POST /pair) - sent on every request
// so the backend can scope data to this branch. See get_branch_context() in
// server.py. null until Setup.jsx completes real pairing.
let deviceToken = null;
export const setDeviceToken = (token) => {
  deviceToken = token || null;
};
export const getDeviceToken = () => deviceToken;

api.interceptors.request.use((cfg) => {
  cfg.headers["X-Actor"] = actorName;
  if (deviceToken) cfg.headers["X-KDS-Device"] = deviceToken;
  return cfg;
});

export const fetchOrderEvents = (id) => api.get(`/orders/${id}/events`).then((r) => r.data);
export const fetchAudit = (limit = 100) => api.get("/audit", { params: { limit } }).then((r) => r.data);
export const fetchWeekly = () => api.get("/stats/weekly").then((r) => r.data);
export const fetchPrinterStatus = () => api.get("/printer/status").then((r) => r.data);
export const sendTestEmail = () => api.post("/reports/test-email").then((r) => r.data);

// Native browser WebSocket can't set custom headers, so the device token
// travels as a query param here instead of X-KDS-Device (see ws_endpoint()).
export const wsUrl = () => {
  const base = `${BACKEND_URL.replace(/^http/, "ws")}/api/ws`;
  return deviceToken ? `${base}?device=${encodeURIComponent(deviceToken)}` : base;
};

export const health = () => api.get("/health").then((r) => r.data);

// Super-admin's platform logo (billing's PlatformSetting 'brand_logo'), same
// mark shown across every Bhojpe product. Cached so the header/sidebar never
// flash the fallback mark on reload while the network call is in flight.
// Chef-login screen image (super-admin → Login Image → Bhojpe KDS), cached
// so it shows instantly on the next load.
const LOGIN_IMAGE_CACHE_KEY = "bhojpe_kds_login_image";
export const getCachedLoginImage = () => {
  try {
    return localStorage.getItem(LOGIN_IMAGE_CACHE_KEY) || null;
  } catch {
    return null;
  }
};
export const fetchLoginImage = () =>
  api.get("/login-image").then((r) => {
    const url = r.data?.url ? `${r.data.url}${r.data.version ? `?v=${r.data.version}` : ""}` : null;
    try {
      if (url) localStorage.setItem(LOGIN_IMAGE_CACHE_KEY, url);
      else localStorage.removeItem(LOGIN_IMAGE_CACHE_KEY);
    } catch {}
    return url;
  });

const LOGO_CACHE_KEY = "bhojpe_kds_brand_logo";
export const getCachedBrandLogo = () => {
  try {
    return localStorage.getItem(LOGO_CACHE_KEY) || null;
  } catch {
    return null;
  }
};
export const fetchBrandLogo = () =>
  api.get("/brand-logo").then((r) => {
    // KDS's own logo (super-admin → Brand Logo → KDS Logo) first, else the platform logo.
    const url = r.data?.kds_url || r.data?.url || null;
    try {
      if (url) localStorage.setItem(LOGO_CACHE_KEY, url);
      else localStorage.removeItem(LOGO_CACHE_KEY);
    } catch {}
    // Browser-tab icon = super-admin's app icon (falls back to the logo).
    const icon = r.data?.icon_url || url;
    if (icon) {
      let link = document.querySelector("link[rel='icon']");
      if (!link) {
        link = document.createElement("link");
        link.rel = "icon";
        document.head.appendChild(link);
      }
      link.href = icon;
    }
    return url;
  });

// Stable per-browser id, generated once and kept in localStorage - lets
// billing recognize "this is the same physical screen" across re-pairs
// (e.g. after clearing localStorage's paired flag but not this id) instead
// of creating a new Device row every time. Separate from deviceToken, which
// is the CURRENT pairing session's identity and does get cleared on logout.
const DEVICE_ID_KEY = "bhojpe_kds_device_id";
const getDeviceIdentifier = () => {
  let id = localStorage.getItem(DEVICE_ID_KEY);
  if (!id) {
    id = (crypto.randomUUID ? crypto.randomUUID() : `${Date.now()}-${Math.random()}`);
    localStorage.setItem(DEVICE_ID_KEY, id);
  }
  return id;
};

export const pair = (syncCode, pairCode) =>
  api.post("/pair", { syncCode, pairCode, deviceIdentifier: getDeviceIdentifier() }).then((r) => r.data);

