import React, { useEffect, useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useKds, ageOf, ageLevel } from "@/state/kdsState";
import { STATUS_ORDER, STATUS_LABEL } from "@/services/mockOrderService";
import { Header } from "@/components/Header";
import { FilterBar } from "@/components/FilterBar";
import { RushIndicator } from "@/components/RushIndicator";
import { DelayAlertBanner } from "@/components/DelayAlertBanner";
import { StatusColumn } from "@/components/StatusColumn";
import { NewOrderAlert } from "@/components/NewOrderAlert";
import { KdsSidebar } from "@/components/KdsSidebar";
import { KotTicketBoard } from "@/components/KotTicketBoard";
import { WifiOff } from "lucide-react";

export default function KDS() {
  const { state, actions, now } = useKds();
  const navigate = useNavigate();
  const [filter, setFilter] = useState("all");
  const [query, setQuery] = useState("");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [mobileStatus, setMobileStatus] = useState("new");

  const [isNarrow, setIsNarrow] = useState(() => window.innerWidth < 768);

  useEffect(() => {
    if (!state.paired) navigate("/setup");
  }, [state.paired, navigate]);

  useEffect(() => {
    const mq = window.matchMedia("(max-width: 767px)");
    const on = (e) => setIsNarrow(e.matches);
    mq.addEventListener("change", on);
    return () => mq.removeEventListener("change", on);
  }, []);

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase();
    return state.orders.filter((o) => {
      if (state.settings.stationFilterOn && o.station !== state.station) return false;
      if (["dine-in", "delivery", "room-service"].includes(filter) && o.type !== filter) return false;
      if (filter === "takeaway" && o.type !== "takeaway" && o.type !== "pickup") return false;
      if (filter === "delayed" && ageLevel(ageOf(o, now).seconds, state.settings.slaMinutes * 60) !== "delayed") return false;
      if (q) {
        const hay = `${o.kot} ${o.table || ""} ${o.refNo || ""}`.toLowerCase();
        if (!hay.includes(q)) return false;
      }
      return true;
    });
  }, [state.orders, state.settings.stationFilterOn, state.station, filter, query, now]);

  const byStatus = (st) => filtered.filter((o) => o.status === st);
  // Filter chips par counts (station filter ke baad, type filter se pehle)
  const counts = useMemo(() => {
    const base = state.orders.filter((o) => !(state.settings.stationFilterOn && o.station !== state.station));
    const c = { all: base.length };
    ["dine-in", "takeaway", "delivery", "room-service"].forEach((t) => { c[t] = base.filter((o) => o.type === t || (t === "takeaway" && o.type === "pickup")).length; });
    c.delayed = base.filter((o) => ageLevel(ageOf(o, now).seconds, state.settings.slaMinutes * 60) === "delayed").length;
    return c;
  }, [state.orders, state.settings.stationFilterOn, state.station, state.settings.slaMinutes, now]);
  const mode = state.settings.displayMode;
  const offline = !state.connection.serverConnected || !state.connection.internet;

  return (
    <div className={`kds-scope mode-${mode} h-screen flex flex-col bg-[#F8F9FA] overflow-hidden`} data-testid="kds-screen">
      <Header onOpenSidebar={() => setSidebarOpen(true)} />

      {offline && (
        <div className="flex items-center gap-2 px-4 py-2 bg-[#FFFBEB] border-b border-[#FDE68A] text-[#92400E] text-sm font-semibold" data-testid="offline-banner">
          <WifiOff className="w-4 h-4" />
          <span className="font-extrabold tracking-wider">● LOCAL MODE</span>
          <span className="hidden sm:inline">Local network active. Orders will sync with server when internet is restored.</span>
        </div>
      )}

      <DelayAlertBanner />

      {/* KOT board (2026-10-07) — Petpooja-style tickets in Bhojpe POS
          Live View colours: per-item "ban gaya" toggle, Food Ready in the
          header, item summary on the left. Old 4-column status board
          (StatusColumn / FilterBar) is kept in the codebase, just unused here. */}
      <main className="flex-1 min-h-0">
        <KotTicketBoard
          stations={state.connection.stations || []}
          stationFilter={state.settings.stationFilterOn ? state.station : "all"}
          onStationFilterChange={(value) => {
            if (value === "all") {
              actions.setSettings({ stationFilterOn: false });
            } else {
              actions.setStation(value);
              actions.setSettings({ stationFilterOn: true });
            }
          }}
        />
      </main>

      <NewOrderAlert />
      <KdsSidebar open={sidebarOpen} onClose={() => setSidebarOpen(false)} />
    </div>
  );
}
